package techguns.gametest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.blocks.*;
import techguns.tileentities.LargeDoorEntity;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class DoorGameTests {
    private static LargeDoorEntity door(GameTestHelper h,int variant,boolean zplane){var block=TGDoors.BLOCKS.get(variant).get();var bottom=h.absolutePos(new BlockPos(2,1,2));h.assertTrue(block.place(h.getLevel(),bottom,zplane,null),"Door fits its nine-block opening");return (LargeDoorEntity)h.getLevel().getBlockEntity(bottom.above());}
    @GameTest(template="empty") public static void everyDoorVariantFormsAndBreaksInBothPlanes(GameTestHelper h){for(int variant=0;variant<4;variant++)for(boolean zplane:new boolean[]{false,true}){var door=door(h,variant,zplane);var center=door.getBlockPos();for(int c=0;c<3;c++)for(int r=0;r<3;r++){var pos=LargeDoorBlock.partPos(center,zplane,c,r);var state=h.getLevel().getBlockState(pos);h.assertTrue(state.is(TGDoors.BLOCKS.get(variant).get())&&LargeDoorBlock.masterPos(pos,state).equals(center),"Each part resolves its own centre, including adjacent structures");}h.getLevel().removeBlock(LargeDoorBlock.partPos(center,zplane,0,0),false);for(int c=0;c<3;c++)for(int r=0;r<3;r++)h.assertTrue(h.getLevel().getBlockState(LargeDoorBlock.partPos(center,zplane,c,r)).isAir(),"Removing any segment dismantles all nine blocks");}var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(new BlockPos(0,0,0))).inflate(8));int count=drops.stream().filter(e->TGDoors.ITEMS.stream().anyMatch(i->e.getItem().is(i.get()))).mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(count==8,"Eight removed doors drop eight items, without nine-block duplication");h.succeed();}
    @GameTest(template="empty") public static void obstructedDoorPlacementChangesNothing(GameTestHelper h){h.setBlock(1,3,2,Blocks.STONE);var block=TGDoors.BLOCKS.get(0).get();h.assertFalse(block.place(h.getLevel(),h.absolutePos(new BlockPos(2,1,2)),false,null),"Any obstructed part rejects the complete placement");h.assertTrue(h.getBlockState(new BlockPos(2,2,2)).isAir()&&h.getBlockState(new BlockPos(1,3,2)).is(Blocks.STONE),"Rejected placement consumes no space and does not replace the obstruction");h.succeed();}
    @GameTest(template="empty") public static void animationAndAutoCloseUseOriginalDurations(GameTestHelper h){var door=door(h,0,false);h.assertTrue(door.toggle(true)&&door.phase()==LargeDoorBlock.Phase.OPENING,"Closed starts opening");h.assertFalse(door.toggle(true),"Clicking during a transition cannot skip its animation");h.assertTrue(door.getBlockState().getCollisionShape(h.getLevel(),door.getBlockPos()).isEmpty(),"Opening removes the source collision immediately");door.changedAt=h.getLevel().getGameTime()-20;door.tick();h.assertTrue(door.phase()==LargeDoorBlock.Phase.OPENED,"Animation completes after twenty game ticks");door.changedAt=h.getLevel().getGameTime()-100;h.runAfterDelay(5,()->{door.tick();h.assertTrue(door.phase()==LargeDoorBlock.Phase.CLOSING,"Manual auto close starts after one hundred ticks open");h.assertFalse(door.getBlockState().getCollisionShape(h.getLevel(),door.getBlockPos()).isEmpty(),"Closing restores source collision immediately");door.changedAt=h.getLevel().getGameTime()-20;door.tick();h.assertTrue(door.phase()==LargeDoorBlock.Phase.CLOSED,"Closing completes without creating a new entity or resetting its settings");h.succeed();});}
    @GameTest(template="empty") public static void doorSettingsAndAnimationSurviveSaving(GameTestHelper h){var door=door(h,3,true);var owner=h.makeMockPlayer();door.access.place(owner);door.access.toggle(owner);door.mode=2;door.redstone=2;door.autoClose=false;door.toggle(false);door.changedAt=h.getLevel().getGameTime()-7;var saved=door.saveWithoutMetadata();var restored=new LargeDoorEntity(door.getBlockPos(),door.getBlockState());restored.setLevel(h.getLevel());restored.load(saved);h.assertTrue(restored.mode==2&&restored.redstone==2&&!restored.autoClose&&restored.access.owner(owner)&&restored.access.restricted(),"Door mode, signal polarity, auto close and owner restriction persist");h.assertTrue(Math.abs(restored.openness(0)-.35f)<.001,"Reload retains the in-flight animation progress");h.succeed();}
    @GameTest(template="empty") public static void redstoneModeUsesEveryDoorSegment(GameTestHelper h){var door=door(h,0,false);door.mode=1;door.redstone=1;door.autoClose=false;h.getLevel().setBlockAndUpdate(door.getBlockPos().offset(1,-1,1),Blocks.REDSTONE_BLOCK.defaultBlockState());h.runAfterDelay(5,()->{door.tick();h.assertTrue(door.phase()==LargeDoorBlock.Phase.OPENING,"Signal beside a lower corner opens the whole door");door.changedAt=h.getLevel().getGameTime()-20;door.tick();h.getLevel().removeBlock(door.getBlockPos().offset(1,-1,1),false);h.runAfterDelay(5,()->{door.tick();h.assertTrue(door.phase()==LargeDoorBlock.Phase.CLOSING,"Losing the signal closes the redstone door");h.succeed();});});}
    @GameTest(template="empty") public static void bunkerDoubleDoorOpensBothLeavesAndBothHalves(GameTestHelper h){var block=TGDoors.BUNKER.get();var a=h.absolutePos(new BlockPos(2,1,2));var b=a.east();for(var pos:new BlockPos[]{a,b})h.getLevel().setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());var state=block.defaultBlockState().setValue(DoorBlock.FACING,Direction.NORTH);h.getLevel().setBlockAndUpdate(a,state.setValue(DoorBlock.HINGE,DoorHingeSide.LEFT));h.getLevel().setBlockAndUpdate(a.above(),state.setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER).setValue(DoorBlock.HINGE,DoorHingeSide.LEFT));h.getLevel().setBlockAndUpdate(b,state.setValue(DoorBlock.HINGE,DoorHingeSide.RIGHT));h.getLevel().setBlockAndUpdate(b.above(),state.setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER).setValue(DoorBlock.HINGE,DoorHingeSide.RIGHT));block.use(h.getLevel().getBlockState(a.above()),h.getLevel(),a.above(),h.makeMockPlayer(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(a.above()),Direction.SOUTH,a.above(),false));for(var pos:new BlockPos[]{a,a.above(),b,b.above()})h.assertTrue(h.getLevel().getBlockState(pos).getValue(DoorBlock.OPEN),"Upper-half click opens both matching leaves and updates all four blocks");h.succeed();}
}
